/**
 * O dinheiro e os pesos da Bíblia — porte de `componentes/viz/dinheiro_biblia.js`.
 *
 * O apêndice B14-B convertido na única unidade que qualquer pessoa entende sem
 * tabela: DIAS DE TRABALHO. Sem essa âncora, "300 denários" e "10.000 talentos"
 * são só palavras, e as parábolas de Jesus perdem exatamente o contraste que as
 * sustenta. Para o dia de trabalho não ficar abstrato também, ele vira reais
 * pelo salário mínimo arredondado: R$ 1.600 por mês ÷ 30 = R$ 53 por dia.
 *
 * - `denario` → a moeda ao lado de uma jornada de 12 horas.
 * - `viuva`   → o denário fatiado em 128 léptons; dois deles = 11 minutos.
 * - `talento` → a BALANÇA: o talento num prato, as minas no outro, até nivelar.
 * - `divida`  → as duas dívidas correndo: a do conservo cabe na tela, a outra não.
 * - `nardo`   → os 300 dias de salário do perfume num calendário de pontos.
 *
 * O estado vem inteiro do renderizador (`info`): a viz só consome.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** A régua em reais: salário mínimo de R$ 1.621 arredondado para R$ 1.600. */
const SALARIO_MES = 1600;
const DIA_REAIS = SALARIO_MES / 30;

/** Valores grandes vão sem centavos. */
function brl(valor: number): string {
  return `R$ ${valor.toLocaleString('pt-BR', { maximumFractionDigits: 0 })}`;
}

/** Os pequenos — a oferta da viúva! — precisam dos centavos. */
function brlCentavos(valor: number): string {
  return valor >= 10
    ? brl(valor)
    : `R$ ${valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

const dinheiro: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Moeda cunhada: relevo, borda serrilhada e brilho varrendo a face. */
  function moeda(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    raio: number,
    cor: string,
    rotulo: string | null,
    tamanhoRotulo: number,
    t: number,
  ): void {
    const relevo = ctx.createRadialGradient(
      cx - raio * 0.35,
      cy - raio * 0.35,
      raio * 0.1,
      cx,
      cy,
      raio,
    );
    relevo.addColorStop(0, '#ffffff');
    relevo.addColorStop(0.35, cor);
    relevo.addColorStop(1, 'rgb(0 0 0 / 35%)');

    ctx.fillStyle = relevo;
    ctx.beginPath();
    ctx.arc(cx, cy, raio, 0, Math.PI * 2);
    ctx.fill();

    // Serrilha da borda.
    ctx.strokeStyle = 'rgb(0 0 0 / 22%)';
    ctx.lineWidth = Math.max(raio * 0.05, 0.8);
    for (let i = 0; i < 36; i++) {
      const angulo = (i / 36) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(angulo) * raio * 0.93, cy + Math.sin(angulo) * raio * 0.93);
      ctx.lineTo(cx + Math.cos(angulo) * raio, cy + Math.sin(angulo) * raio);
      ctx.stroke();
    }

    ctx.strokeStyle = 'rgb(0 0 0 / 25%)';
    ctx.lineWidth = Math.max(raio * 0.06, 1);
    ctx.beginPath();
    ctx.arc(cx, cy, raio * 0.82, 0, Math.PI * 2);
    ctx.stroke();

    // O perfil cunhado — o "César" da moeda —, sugerido numa curva só.
    ctx.strokeStyle = 'rgb(0 0 0 / 20%)';
    ctx.lineWidth = Math.max(raio * 0.07, 1);
    ctx.beginPath();
    ctx.arc(cx, cy - raio * 0.06, raio * 0.42, Math.PI * 0.85, Math.PI * 1.95);
    ctx.stroke();

    // Brilho varrendo a face: é o que faz a moeda parecer metal.
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, raio * 0.95, 0, Math.PI * 2);
    ctx.clip();
    const foco = cx - raio + (((t * 0.35) % 1.6) - 0.3) * raio * 2;
    const brilho = ctx.createLinearGradient(foco - raio * 0.3, 0, foco + raio * 0.3, 0);
    brilho.addColorStop(0, 'rgb(255 255 255 / 0%)');
    brilho.addColorStop(0.5, 'rgb(255 255 255 / 45%)');
    brilho.addColorStop(1, 'rgb(255 255 255 / 0%)');
    ctx.fillStyle = brilho;
    ctx.fillRect(cx - raio, cy - raio, raio * 2, raio * 2);
    ctx.restore();

    if (rotulo !== null) {
      texto(ctx, rotulo, cx, cy, tamanhoRotulo, { cor: '#ffffff', peso: 800 });
    }
  }

  // ── Fase 1 · o denário vale um dia de trabalho ────────────────────────────
  function faseDenario(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const escolhido = textoDe(estado, 'escolhido');
    const certo = escolhido === 'dia';

    titulo(ctx, L, A, 'Um denário vale quanto tempo de trabalho?');

    const raio = limitar(A * 0.13, 24, 56);
    moeda(
      ctx,
      L * 0.17,
      A * 0.34,
      raio,
      certo ? cor.ouro : MATERIAIS.prata,
      'D',
      limitar(A * 0.085, 14, 32),
      t,
    );
    etiqueta(
      ctx,
      'denário · 3,85 g',
      L * 0.17,
      A * 0.34 + raio + A * 0.06,
      limitar(A * 0.04, 9, 13),
    );
    etiqueta(
      ctx,
      `≈ ${brl(DIA_REAIS)} por dia`,
      L * 0.17,
      A * 0.34 + raio + A * 0.13,
      limitar(A * 0.042, 9, 14),
      certo ? cor.verde : cor.texto,
      800,
    );
    texto(
      ctx,
      `${brl(SALARIO_MES)} ÷ 30 dias`,
      L * 0.17,
      A * 0.34 + raio + A * 0.19,
      limitar(A * 0.036, 8, 12),
      { cor: cor.fraco, peso: 600 },
    );

    // As 12 horas da jornada, uma barrinha cada — acendem em cascata ao acertar.
    const x0 = L * 0.38;
    const largura = L * 0.55;
    const altura = limitar(A * 0.15, 22, 56);
    const y = A * 0.26;
    const celula = largura / 12;

    for (let i = 0; i < 12; i++) {
      const onda = certo ? limitar(Math.sin(t * 2 - i * 0.35) * 0.5 + 0.75, 0.4, 1) : 1;
      ctx.save();
      ctx.globalAlpha = onda;
      retangulo(ctx, x0 + i * celula + 2, y, celula - 4, altura, 3, certo ? cor.ouro : cor.trilho);
      ctx.restore();
      texto(
        ctx,
        `${i + 1}`,
        x0 + i * celula + celula / 2,
        y + altura + limitar(A * 0.028, 7, 10),
        limitar(A * 0.028, 7, 10),
        { cor: cor.fraco, peso: 600 },
      );
    }

    retangulo(ctx, x0, y - 4, largura, altura + 8, 6, undefined, certo ? cor.ouro : cor.fraco, 2);
    etiqueta(
      ctx,
      'jornada de 12 horas',
      x0 + largura / 2,
      y + altura + limitar(A * 0.075, 16, 28),
      limitar(A * 0.042, 10, 14),
      certo ? cor.ouro : cor.fraco,
      800,
    );

    // As três alternativas na mesma escala: a base é a jornada, e "vários meses"
    // sai fora dela de propósito — o contraste é o que responde à pergunta.
    const alturaBarra = limitar(A * 0.045, 7, 15);
    const unidade = L * 0.3;
    const alternativas = [
      { id: 'pao', rotulo: 'um pão', fracao: 1 / 12 },
      { id: 'dia', rotulo: 'um dia de trabalho', fracao: 1 },
      { id: 'fortuna', rotulo: 'vários meses', fracao: 1.7 },
    ];

    let yy = A * 0.7;
    for (const alternativa of alternativas) {
      const marcada = escolhido === alternativa.id;
      const boa = alternativa.id === 'dia';

      retangulo(
        ctx,
        x0,
        yy,
        unidade * alternativa.fracao,
        alturaBarra,
        3,
        marcada ? (boa ? cor.verde : cor.erro) : boa && certo ? cor.verde : cor.trilho,
      );
      texto(ctx, alternativa.rotulo, x0 - 10, yy + alturaBarra / 2, limitar(A * 0.04, 9, 12), {
        cor: marcada ? (boa ? cor.verde : cor.erro) : cor.fraco,
        peso: marcada || boa ? 800 : 500,
        alinhamento: 'right',
      });
      yy += alturaBarra * 1.45;
    }

    const aviso =
      escolhido === ''
        ? 'Escolha o que um denário comprava.'
        : certo
          ? 'Um denário = um dia de 12 horas. Guarde essa régua. ✔'
          : 'Nem troco, nem fortuna: era o salário de um dia.';

    texto(ctx, aviso, L / 2, A * 0.95, limitar(A * 0.048, 10, 15), {
      cor: certo ? cor.verde : escolhido === '' ? cor.fraco : cor.erro,
      peso: 700,
    });
  }

  // ── Fase 2 · o denário fatiado em léptons ─────────────────────────────────
  function faseViuva(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const leptons = numeroDe(info, 'leptons', 8);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A moedinha da viúva dentro de um denário');

    // O denário como disco fatiado: em 128 a fatia fica ridícula, que é a lição.
    const cx = L * 0.27;
    const cy = A * 0.45;
    const raio = limitar(Math.min(L * 0.18, A * 0.26), 28, 120);

    moeda(ctx, cx, cy, raio, MATERIAIS.prata, null, 0, t);

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, raio * 0.95, 0, Math.PI * 2);
    ctx.clip();
    ctx.strokeStyle = 'rgb(255 255 255 / 85%)';
    ctx.lineWidth = 1;
    for (let i = 0; i < leptons; i++) {
      const angulo = (i / leptons) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(angulo) * raio, cy + Math.sin(angulo) * raio);
      ctx.stroke();
    }
    ctx.restore();

    // As DUAS fatias da viúva, destacadas e pulsando devagar.
    ctx.save();
    ctx.globalAlpha = 0.75 + Math.sin(t * 2.2) * 0.25;
    ctx.fillStyle = ok ? cor.verde : cor.ouro;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, raio * 0.95, -Math.PI / 2, -Math.PI / 2 + (2 / leptons) * Math.PI * 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    etiqueta(
      ctx,
      `1 denário = ${leptons} léptons`,
      cx,
      cy + raio + limitar(A * 0.075, 15, 28),
      limitar(A * 0.048, 11, 16),
      cor.texto,
      800,
    );

    // As duas moedinhas dela, em tamanho de verdade ao lado da grande.
    const raioPequeno = Math.max(raio * 0.13, 5);
    moeda(ctx, cx + raio * 1.35, cy + raio * 0.75, raioPequeno, MATERIAIS.cobre, null, 0, t);
    moeda(
      ctx,
      cx + raio * 1.35 + raioPequeno * 2.6,
      cy + raio * 0.75,
      raioPequeno,
      MATERIAIS.cobre,
      null,
      0,
      t,
    );

    // A mesma fração lida em minutos da jornada de 12 h (720 min).
    const minutos = (720 * 2) / leptons;
    const corDoValor = ok ? cor.verde : cor.texto;

    texto(ctx, 'as duas moedinhas dela valem', L * 0.7, A * 0.3, limitar(A * 0.045, 10, 14), {
      cor: cor.fraco,
      peso: 600,
    });
    texto(
      ctx,
      minutos >= 60
        ? `${(minutos / 60).toFixed(1).replace('.', ',')} h`
        : `${minutos.toFixed(0)} min`,
      L * 0.7,
      A * 0.45,
      limitar(A * 0.15, 22, 52),
      { cor: corDoValor, peso: 800 },
    );
    texto(ctx, 'de trabalho', L * 0.7, A * 0.57, limitar(A * 0.042, 9, 14), {
      cor: cor.fraco,
      peso: 600,
    });
    etiqueta(
      ctx,
      `≈ ${brlCentavos((DIA_REAIS * 2) / leptons)}`,
      L * 0.7,
      A * 0.66,
      limitar(A * 0.045, 10, 15),
      corDoValor,
      800,
    );
    texto(ctx, 'pelo salário mínimo de hoje', L * 0.7, A * 0.72, limitar(A * 0.036, 8, 12), {
      cor: cor.fraco,
      peso: 600,
    });
    texto(ctx, '64 quadrantes × 2 léptons cada', L / 2, A * 0.86, limitar(A * 0.042, 9, 14), {
      cor: cor.fraco,
      peso: 600,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      '128 léptons: 11 minutos — menos de R$ 1. ✔',
      'Ajuste até fechar a conta do denário.',
    );
  }

  // ── Fase 3 · a balança: o talento contra as minas ─────────────────────────
  //
  // Três blocos parados não dão ideia de peso. Uma balança dá: o talento fica
  // num prato, as minas vão para o outro, e o braço só nivela quando as sessenta
  // entram. Enquanto não nivela, ele oscila.
  function faseTalento(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const kg = numeroDe(info, 'kg', 0);
    const minas = Math.round(numeroDe(info, 'minas', 0));
    const ok = info.ok === true;

    titulo(ctx, L, A, 'A balança: quantas minas fazem um talento?');

    const px = L / 2;
    const py = A * 0.26;
    const braco = L * 0.26;
    const diferenca = limitar((kg - 34.2) / 34.2, -1, 1);
    // 1 = pratos empatados.
    const perto = 1 - Math.min(Math.abs(diferenca) * 4, 1);
    // A oscilação morre à medida que os pratos empatam.
    const balanco = ok ? Math.sin(t * 2.4) * 0.012 : Math.sin(t * 3.6) * 0.05 * (1 - perto * 0.7);
    const angulo = diferenca * 0.3 + balanco;

    retangulo(ctx, px - L * 0.012, py, L * 0.024, A * 0.42, L * 0.01, MATERIAIS.madeira);
    retangulo(ctx, px - L * 0.07, A * 0.66, L * 0.14, A * 0.035, A * 0.015, MATERIAIS.madeira);

    const ex = Math.cos(angulo) * braco;
    const ey = Math.sin(angulo) * braco;

    ctx.strokeStyle = '#6f5a3c';
    ctx.lineWidth = limitar(A * 0.018, 3, 8);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(px - ex, py - ey);
    ctx.lineTo(px + ex, py + ey);
    ctx.stroke();

    ctx.fillStyle = cor.ouro;
    ctx.beginPath();
    ctx.arc(px, py, limitar(A * 0.02, 4, 9), 0, Math.PI * 2);
    ctx.fill();

    /** Um prato pendurado na ponta do braço. */
    const prato = (cx: number, cy: number, corPrato: string): { yPrato: number } => {
      const largura = L * 0.19;
      const profundidade = A * 0.05;

      ctx.strokeStyle = MATERIAIS.corda;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx - largura / 2, cy + A * 0.11);
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + largura / 2, cy + A * 0.11);
      ctx.stroke();

      const yPrato = cy + A * 0.11;
      ctx.fillStyle = corPrato;
      ctx.beginPath();
      ctx.moveTo(cx - largura / 2, yPrato);
      ctx.quadraticCurveTo(cx, yPrato + profundidade * 2.4, cx + largura / 2, yPrato);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#5c6580';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(cx - largura / 2, yPrato);
      ctx.lineTo(cx + largura / 2, yPrato);
      ctx.stroke();

      return { yPrato };
    };

    const esquerdo = prato(px - ex, py - ey, '#9aa4bd');
    const direito = prato(px + ex, py + ey, '#9aa4bd');

    // Prato esquerdo: UM talento, o alvo, sempre igual.
    const lado = limitar(A * 0.11, 20, 52);
    const ouro = ctx.createLinearGradient(0, esquerdo.yPrato - lado, 0, esquerdo.yPrato);
    ouro.addColorStop(0, '#e2b64a');
    ouro.addColorStop(1, cor.ouro);
    retangulo(
      ctx,
      px - ex - lado / 2,
      esquerdo.yPrato - lado,
      lado,
      lado,
      4,
      ouro,
      'rgb(0 0 0 / 25%)',
      1.5,
    );
    etiqueta(
      ctx,
      '1 talento · 34,2 kg',
      px - ex,
      esquerdo.yPrato + A * 0.05,
      limitar(A * 0.04, 9, 13),
      cor.texto,
      800,
    );

    // Prato direito: a pilha de minas que o investigador empilha.
    const quantas = Math.min(minas, 60);
    const larguraMina = L * 0.019;
    const alturaMina = A * 0.017;
    for (let i = 0; i < quantas; i++) {
      const coluna = i % 10;
      const linha = Math.floor(i / 10);
      retangulo(
        ctx,
        px + ex - larguraMina * 5 + coluna * larguraMina,
        direito.yPrato - alturaMina * (linha + 1) - linha * 1.5,
        larguraMina - 1.5,
        alturaMina,
        1.5,
        MATERIAIS.cobre,
        'rgb(0 0 0 / 20%)',
        0.8,
      );
    }
    etiqueta(
      ctx,
      `${minas} ${minas === 1 ? 'mina' : 'minas'} · ${kg.toFixed(1).replace('.', ',')} kg`,
      px + ex,
      direito.yPrato + A * 0.05,
      limitar(A * 0.04, 9, 13),
      ok ? cor.verde : cor.texto,
      800,
    );

    // A escada de referência, discreta, no rodapé da cena. O lado do quadrado
    // vem da raiz do peso: 34,2 kg contra 11,4 g não caberia numa escala linear.
    const escada = [
      { rotulo: 'siclo · 11,4 g', gramas: 11.4, cor: MATERIAIS.prata },
      { rotulo: 'mina · 570 g · 50 siclos', gramas: 570, cor: MATERIAIS.cobre },
      { rotulo: 'talento · 34,2 kg · 60 minas', gramas: 34200, cor: cor.ouro },
    ];

    const chao = A * 0.79;
    let x = L * 0.17;
    for (const peca of escada) {
      const lado = limitar(Math.sqrt(peca.gramas) * (A * 0.0032), A * 0.028, A * 0.13);
      retangulo(ctx, x - lado / 2, chao - lado, lado, lado, 3, peca.cor, 'rgb(0 0 0 / 15%)', 1);
      texto(ctx, peca.rotulo, x, chao + limitar(A * 0.04, 9, 15), limitar(A * 0.034, 8, 12), {
        cor: cor.fraco,
        peso: 700,
      });
      x += L * 0.33;
    }

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(L * 0.06, chao);
    ctx.lineTo(L * 0.94, chao);
    ctx.stroke();

    rodape(
      ctx,
      L,
      A,
      ok,
      'Nivelou: 60 minas = 34,2 kg. ✔',
      minas > 60 ? 'Passou do peso: tire minas.' : 'Empilhe minas até nivelar.',
    );
  }

  // ── Fase 4 · as duas dívidas da parábola ──────────────────────────────────
  //
  // A cena não pode ser um gráfico parado: a lição é que uma das dívidas NÃO
  // CABE. Então a barra grande escoa para fora da tela sem parar, e o contador
  // de dias sobe do zero aos 60 milhões repetidamente, sem nunca assentar.
  function faseDivida(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const escolhido = textoDe(estado, 'escolhido');
    const certo = escolhido === '600000';

    titulo(ctx, L, A, 'As duas dívidas, na mesma escala');

    const x0 = L * 0.1;
    const largura = L * 0.82;
    const altura = limitar(A * 0.11, 18, 44);

    // Dívida do conservo: 100 dias, e eles cabem contados na tela.
    const y1 = A * 0.22;
    retangulo(ctx, x0, y1, largura, altura, 4, cor.fundo, cor.trilho, 1);

    const passoPonto = (largura * 0.16) / 20;
    for (let i = 0; i < 100; i++) {
      const coluna = i % 20;
      const linha = Math.floor(i / 20);
      ctx.fillStyle = cor.azulClaro;
      ctx.beginPath();
      ctx.arc(
        x0 + 6 + coluna * passoPonto + passoPonto / 2,
        y1 + altura * 0.18 + linha * (altura * 0.16),
        Math.max(passoPonto * 0.22, 1),
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
    texto(
      ctx,
      `100 dias (${brl(100 * DIA_REAIS)}) — o que ele foi cobrar`,
      x0 + largura * 0.19,
      y1 + altura / 2,
      limitar(A * 0.04, 9, 12),
      { cor: cor.texto, peso: 700, alinhamento: 'left' },
    );

    // Dívida do escravo: o mesmo ponto vale um dia, mas o campo escoa sem fim.
    const y2 = A * 0.44;
    const escoando = ctx.createLinearGradient(x0, 0, x0 + largura + L * 0.12, 0);
    escoando.addColorStop(0, certo ? cor.verde : cor.ouro);
    escoando.addColorStop(0.75, certo ? cor.verde : cor.ouro);
    escoando.addColorStop(1, 'rgb(176 125 16 / 8%)');
    retangulo(ctx, x0, y2, largura + L * 0.12, altura, 4, escoando);

    ctx.save();
    ctx.beginPath();
    ctx.roundRect(x0, y2, largura + L * 0.12, altura, 4);
    ctx.clip();
    ctx.fillStyle = 'rgb(255 255 255 / 35%)';
    const periodo = L * 0.035;
    const deslocamento = (t * L * 0.09) % periodo;
    for (let x = x0 - periodo; x < x0 + largura + L * 0.14; x += periodo) {
      for (let linha = 0; linha < 3; linha++) {
        ctx.beginPath();
        ctx.arc(
          x + deslocamento,
          y2 + altura * 0.25 + linha * (altura * 0.25),
          Math.max(periodo * 0.06, 1),
          0,
          Math.PI * 2,
        );
        ctx.fill();
      }
    }
    ctx.restore();

    texto(
      ctx,
      '60.000.000 de dias — o que lhe foi perdoado',
      x0 + 10,
      y2 + altura / 2,
      limitar(A * 0.042, 9, 13),
      { cor: '#ffffff', peso: 800, alinhamento: 'left' },
    );

    // O aviso pulsa: a barra segue muito além da tela.
    const pulso = 1 + Math.sin(t * 3) * 0.12;
    texto(
      ctx,
      'segue por 200.000 anos →',
      x0 + largura * 0.72,
      y2 + altura * 1.6,
      limitar(A * 0.04, 9, 13) * pulso,
      { cor: cor.fraco, peso: 700 },
    );

    // Contador subindo do zero aos 60 milhões, em ciclo — nunca assenta.
    const ciclo = (t % 7) / 7;
    const suavizado = 1 - (1 - ciclo) ** 3;
    const dias = Math.round(60000000 * suavizado);

    texto(ctx, `${ptBR(dias)} dias`, L / 2, A * 0.68, limitar(A * 0.085, 16, 30), {
      cor: certo ? cor.verde : cor.texto,
      peso: 800,
    });
    texto(
      ctx,
      `${brl(dias * DIA_REAIS)} — e o contador ainda está subindo`,
      L / 2,
      A * 0.755,
      limitar(A * 0.042, 9, 14),
      { cor: cor.fraco, peso: 700 },
    );

    const corDoVeredito = certo ? cor.verde : escolhido === '' ? cor.texto : cor.erro;
    texto(
      ctx,
      '10.000 talentos × 6.000 dracmas ÷ 100 denários',
      L / 2,
      A * 0.83,
      limitar(A * 0.042, 9, 14),
      { cor: cor.fraco, peso: 600 },
    );
    texto(ctx, certo ? '600.000 ×' : '? ×', L / 2, A * 0.89, limitar(A * 0.1, 18, 36), {
      cor: corDoVeredito,
      peso: 800,
    });

    const aviso =
      escolhido === ''
        ? 'Quantas vezes maior era a dívida perdoada?'
        : certo
          ? 'Seiscentas mil vezes maior. Impossível errar a moral. ✔'
          : 'Refaça: 10.000 talentos, não um só.';

    texto(ctx, aviso, L / 2, A * 0.95, limitar(A * 0.048, 10, 15), {
      cor: corDoVeredito,
      peso: 700,
    });
  }

  // ── Fase 5 · os 300 dias de salário do perfume ────────────────────────────
  function faseNardo(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const meses = numeroDe(info, 'meses', 1);
    const ok = info.ok === true;
    const reais = meses * SALARIO_MES;

    titulo(ctx, L, A, 'O perfume de Maria em dias de salário');

    // Frasco de alabastro à esquerda, com o perfume oscilando dentro.
    const fx = L * 0.14;
    const fy = A * 0.24;
    const fw = limitar(L * 0.1, 30, 80);
    const fh = A * 0.32;

    retangulo(ctx, fx, fy + fh * 0.22, fw, fh * 0.78, fw * 0.3, '#f3ece0', cor.ouro, 2.5);
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(fx + 3, fy + fh * 0.22 + 3, fw - 6, fh * 0.78 - 6, fw * 0.28);
    ctx.clip();
    const nivel = fy + fh * 0.45 + Math.sin(t * 1.6) * fh * 0.012;
    ctx.fillStyle = 'rgb(176 125 16 / 45%)';
    ctx.fillRect(fx, nivel, fw, fh);
    ctx.restore();
    retangulo(ctx, fx + fw * 0.34, fy, fw * 0.32, fh * 0.26, 3, '#f3ece0', cor.ouro, 2.5);

    etiqueta(
      ctx,
      'nardo genuíno',
      fx + fw / 2,
      fy + fh + limitar(A * 0.06, 12, 22),
      limitar(A * 0.042, 10, 14),
      cor.texto,
      800,
    );
    texto(
      ctx,
      '1 libra romana · 327 g',
      fx + fw / 2,
      fy + fh + limitar(A * 0.115, 24, 38),
      limitar(A * 0.038, 9, 12),
      { cor: cor.fraco, peso: 600 },
    );

    // Calendário de 300 pontos (dias de trabalho); acende conforme o slider.
    const colunas = 30;
    const linhas = 10;
    const acesos = Math.min(meses * 30, 300);
    const gx = L * 0.38;
    const gw = L * 0.54;
    const gy = A * 0.2;
    const gh = A * 0.4;
    const larguraCelula = gw / colunas;
    const alturaCelula = gh / linhas;
    const raio = Math.max(Math.min(larguraCelula, alturaCelula) * 0.3, 1.5);

    for (let i = 0; i < colunas * linhas; i++) {
      const cx = gx + (i % colunas) * larguraCelula + larguraCelula / 2;
      const cy = gy + Math.floor(i / colunas) * alturaCelula + alturaCelula / 2;
      // O mês recém-aceso pulsa: mostra o que o último passo do slider somou.
      const recente = i >= acesos - 30 && i < acesos;

      ctx.fillStyle = i < acesos ? (ok ? cor.verde : cor.ouro) : cor.trilho;
      ctx.beginPath();
      ctx.arc(cx, cy, recente ? raio * (1.15 + Math.sin(t * 4) * 0.2) : raio, 0, Math.PI * 2);
      ctx.fill();
    }

    texto(
      ctx,
      '300 dias de trabalho (cada ponto = um dia)',
      gx + gw / 2,
      gy + gh + limitar(A * 0.055, 12, 20),
      limitar(A * 0.04, 9, 13),
      { cor: cor.fraco, peso: 600 },
    );

    const corDoValor = ok ? cor.verde : cor.texto;
    texto(ctx, brl(reais), L * 0.66, A * 0.73, limitar(A * 0.095, 18, 34), {
      cor: corDoValor,
      peso: 800,
    });
    texto(
      ctx,
      `${meses} × ${brl(SALARIO_MES)} de salário mínimo`,
      L * 0.66,
      A * 0.8,
      limitar(A * 0.04, 9, 13),
      { cor: cor.fraco, peso: 600 },
    );
    texto(
      ctx,
      `${meses} ${meses === 1 ? 'mês' : 'meses'} = ${meses * 30} dias`,
      L * 0.19,
      A * 0.75,
      limitar(A * 0.055, 12, 20),
      { cor: corDoValor, peso: 800 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      `Dez meses de salário — ${brl(300 * DIA_REAIS)} — num frasco. ✔`,
      'Ajuste até os 300 dias fecharem.',
    );
  }

  const FASES: Readonly<
    Record<string, (ctx: CanvasRenderingContext2D, L: number, A: number, t: number) => void>
  > = {
    denario: faseDenario,
    viuva: faseViuva,
    talento: faseTalento,
    divida: faseDivida,
    nardo: faseNardo,
  };

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => {
      const fase = textoDe(infoDe(estado), 'fase');
      (FASES[fase] ?? faseDenario)(ctx, L, A, t);
    },
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default dinheiro;
